--- from: Assets/BundleResources/Prefabs/Welfare/WelfareMainDialog.prefab > name: WelfareMainDialog
---@class UIWelfareMainDialog
---@field Env                            UIWelfareMainDialog
---@field controller                        Engine.UI.UILuaDialog
---@field ImgBg                            UnityEngine.RectTransform                @ 0
