local UIWelfareMainDialog = Class("UIWelfareMainDialog")
function UIWelfareMainDialog:__init()
    self._toggleData = {}        --页签是数据
    ---@type WelfareDojo[]
    self._allWelfareDojo = {}
    self._selectedIndex = 1         --但前打开的 福利页
    self._activityNodes = {}
    -- self._loaders         = {}
end

function UIWelfareMainDialog:__delete()
    self._toggleData = nil
    self._allWelfareDojo = nil
    self._selectedIndex = nil
    self._activityNodes = nil
end

function UIWelfareMainDialog:Awake()
    --self.controller.MarkPoolable = true
end

function UIWelfareMainDialog:OnFocus(focus)
    if focus then
        local node = self._activityNodes[tostring(self._selectedIndex)]
        if node and not isNull(node.go) and node.scr then
            if node.scr.RefreshCurrencyBarInfo then
                node.scr:RefreshCurrencyBarInfo()
            end
        end
    end
end

function UIWelfareMainDialog:InitToggleData()
    self._toggleData = {}
    if not self._allWelfareDojo then
        return
    end
    for i, v in ipairs(self._allWelfareDojo) do
        local dojo = v
        table.insert(self._toggleData, {
            dojo = dojo,
            func = function()
                if checkNumber(dojo.welfareId) == WelfareConstants.OpenIds.DailySin then
                    xRecord.record('4-006')
                elseif checkNumber(dojo.welfareId) == WelfareConstants.OpenIds.MonthlyMembership then
                    xRecord.record('4-001')
                elseif checkNumber(dojo.welfareId) == WelfareConstants.OpenIds.CumulativeCharge then
                    xRecord.record('4-011')
                elseif checkNumber(dojo.welfareId) == WelfareConstants.OpenIds.ADRewards then
                    xRecord.record('4-013')
                end
                self:RefreshNode(dojo.index)
            end,
        })
    end
end

function UIWelfareMainDialog:FillSelf()
    local scr = CfUtils.GetLuaScr(self.ActivityTabToggleLeft, ActivityTabToggleLeft)
    if scr then
        scr:FillToggles(self._toggleData, self._selectedIndex)
    end
    self:RefreshNode(self._selectedIndex)
end
---外部用来刷新自己的 从一个页签切换到另一个可以用这个方法
function UIWelfareMainDialog:RefreshSelfByIndex(index)
    local scr = CfUtils.GetLuaScr(self.ActivityTabToggleLeft, ActivityTabToggleLeft)
    if scr then
        scr:FillToggles(self._toggleData, index)
    end
    self:RefreshNode(index)
end

--刷新节点
function UIWelfareMainDialog:RefreshNode(index)
    local dojo = self:GetDojoByIndex(index)
    if not dojo then
        return
    end

    --先注销当前选择的
    if checkNumber(self._selectedIndex) ~= 0 then
        local lastDojo = self:GetDojoByIndex(self._selectedIndex)
        if lastDojo then
            local node = self._activityNodes[tostring(self._selectedIndex)]
            if node and node.go then
                node.go.transform.anchoredPosition3D = Vector3(0, 0, 0)
                local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
                canvas.enabled = false
                ---@type UnityEngine.MeshRenderer[]
                local rendererList = node.go.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.MeshRenderer))
                if not isNull(rendererList) then
                    for i = 1, rendererList.Length do
                        rendererList[i - 1].enabled = false
                    end
                end
            end
        end
    end

    self:ShowActivityNode(index)
end

function UIWelfareMainDialog:ShowActivityNode(index)
    if not index then
        return
    end

    local dojo = self:GetDojoByIndex(index)
    local bgImage = checkString(dojo.bgImage)
    if bgImage == '' then
        bgImage = checkString(dojo.entranceImage)
    end
    self:RefreshBg(bgImage)
    if dojo.isOpenNav then
        ServerDifferenceMgr:RefreshNavigatorGoods(true)
        -- 还原顶部导航栏
    else
        ServerDifferenceMgr:RefreshNavigatorGoods(false)
    end
    if self._activityNodes[tostring(index)] then
        self:RefreshActivityNode(index)
    else
        self:CreateActivityNode(index)
    end
end

function UIWelfareMainDialog:RefreshActivityNode(index)
    self._selectedIndex = index
    local dojo = self:GetDojoByIndex(index)
    local node = self._activityNodes[tostring(index)]
    if node and not isNull(node.go) and node.scr then
        --KTool.SetActive(node.go, true)
        local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
        canvas.enabled = true
        ---@type UnityEngine.MeshRenderer[]
        local rendererList = node.go.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.MeshRenderer))
        if not isNull(rendererList) then
            for i = 1, rendererList.Length do
                rendererList[i - 1].enabled = true
            end
        end
        node.scr:Refresh(dojo, self._selectedIndex)
    end
end

---刷新背景
---@param path string 服务器返回的背景路径
function UIWelfareMainDialog:RefreshBg(path)
    if checkString(path) == '' then
        return
    end
    CfUtils.FillImage(self.ImgBg, path)
end

---创建一个活动页面
---@param activityId number 活动id
---@return table
function UIWelfareMainDialog:CreateActivityNode(index)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            local dojo = self:GetDojoByIndex(index)
            local config = WelfareConstants.Configs[tostring(dojo.welfareId)]
            if not config then
                return {}
            end
            local go = nil
            if config.prefabPath then
                local path = string.format("%s.prefab", config.prefabPath)
                go = GameUtils.LoadBundleAsync(path, self.ActivityNodeGroup.gameObject, false)
            else
                go = GameUtils.LoadBundleAsyncById(config.prefabId, self.ActivityNodeGroup.gameObject, false, true)
            end
            local scr = CfUtils.GetLuaScr(go, config.scrPath)
            -- self:AddLoader(loader)
            local node = {
                go = go,
                scr = scr,
            }
            self._activityNodes[tostring(index)] = node
            self:RefreshActivityNode(index)
        end)
    end)
end

--获取dojo
---@return WelfareDojo,number
function UIWelfareMainDialog:GetDojoByIndex(selectedIndex)
    local dojo = nil
    for index, v in pairs(self._allWelfareDojo) do
        if index == selectedIndex then
            dojo = v
            break
        end
    end
    return dojo, selectedIndex
end

function UIWelfareMainDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams = CfUtils.DialogSafeParameters(self.controller)

        -- 检测是否 需要还原后退回来的位置
        local prevSelectedIndex = checkInt(initParams.prevSelectedIndex)
        if prevSelectedIndex > 0 then
            self._selectedIndex = prevSelectedIndex
        end

        self:RefreshSelf()
    end)
end

function UIWelfareMainDialog:GetIndexByWelfareId(welfareId)
    welfareId = checkInt(welfareId)
    local index = 1
    for k, v in pairs(self._allWelfareDojo) do
        if checkInt(v.welfareId) == welfareId then
            index = k
            break
        end
    end
    return index
end

---初始化 WelfareDojo
function UIWelfareMainDialog:InitWelfareDojo()
    local isWhitLevelGiftFinished = true
    ---手动添加一个小红点
    ---@type WhiteLevelGiftComponent
    local whiteLevelGiftComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.WhiteLevelGiftComponent)
    if whiteLevelGiftComponent then
        -----@type PlayerComponent
        --local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        --local playerLevel = checkNumber(playerComponent.playerDojo.level)
        for i, v in pairs(whiteLevelGiftComponent.whiteLevelGift) do
            if checkNumber(v.hasBuy) == 0 then
                isWhitLevelGiftFinished = false
            end
            --if checkNumber(playerLevel) >= checkNumber(v.level) and checkNumber(v.hasBuy) == 0 then
            --    execute_task_everyday_hour('WHITE_LEVEL_GIFT', 5, function()
            --        GameUtils.SetRedPointNum(Constants.RedPointConst.WhiteLevelGift , 1)
            --        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.WhiteLevelGift)
            --    end, function()
            --        ---已经弹出过
            --        GameUtils.SetRedPointNum(Constants.RedPointConst.WhiteLevelGift , 0)
            --        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.WhiteLevelGift)
            --    end)
            --    break
            --end
        end
    end
    local activities = WelfareConstants.Configs
    local keys = {}
    local isDowndloadPlaying = ThirdDownloadManager:IsDownloadAndPlaying()
    for k, v in pairs(activities) do
        local isOpenId = CfUtils.IsOpneByFunctionId(v.functionId)
        if isOpenId and (not (isDowndloadPlaying and checkNumber(v.welfareId) == WelfareConstants.OpenIds.CumulativeCharge)) then
            if checkNumber(v.welfareId) == WelfareConstants.OpenIds.ADRewards then
                if self:isOpenAdRewards() then
                    keys[#keys + 1] = k
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.WhiteLevelGift then
                if not isWhitLevelGiftFinished and CfUtils.IsOpneByFunctionId(Constants.SystemToggleIds.Id1111) then
                    keys[#keys + 1] = k
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.DailySin then
                ---@type PlayerComponent
                local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                local isOpenPlayerEntry = PlayerComponent:IsPopPlayerEntryWelfare()
                if not isOpenPlayerEntry then
                    keys[#keys + 1] = k
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.NightmarePassCard then
                local sysTemId = checkInt(v.functionId)
                local isUnlock = GameUtils.IsUnlockedBySystemTogId(sysTemId)
                ---@type SystemToggleVo
                local systemToggleVo = CfUtils.SystemToggleVo( sysTemId)
                if not isUnlock and checkNumber(systemToggleVo.lockShowType) == Constants.ModelFunctionLockShowType.Hide then
                    -- 未解锁时，并且表现配置要求隐藏，则不显示
                else
                    keys[#keys + 1] = k
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.AccountBind then
                if GameUtils.isAccountBindFunction() then
                    -----@type PlayerComponent
                    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    if playerComponent and checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 then
                        ---是游客的情况下
                        keys[#keys + 1] = k
                    end
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.ResidentAdventure then
                ---@type SDKService
                local SDKService = import('Game.Entry.SDKService')
                local isUnLock = GameUtils.IsUnlockedBySystemTogId(v.functionId) and (not SDKService:IsDmm())
                if isUnLock then
                    local playerDojo = GameUtils.GetPlayerDojo()
                    if not playerDojo:IsGetWelfareJumpRewards() then
                        keys[#keys + 1] = k
                    end
                end
            elseif checkNumber(v.welfareId) == WelfareConstants.OpenIds.VipFund then
                ---vip福利是否开始的逻辑
                -----@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                if playerComponent and checkNumber(playerComponent.playerDojo.showVip) == 1 then
                    keys[#keys + 1] = k
                end
            elseif checkInt(v.welfareId) == WelfareConstants.OpenIds.JPMailBind then
                ---计算一下设置中是否存在绑定手机相关的小红点
                if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id277) then
                    ---@type SDKService
                    local sdkService =  import('Game.Entry.SDKService'):GetInstance()
                    if sdkService:IsForeignSDK() or KTool.UNITY_EDITOR() then
                        -----@type UserComponent
                        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                        if userComponent and checkNumber(userComponent.userInfo.bindTerminalRewards) == 0 then
                            ---再添加是否已取过的判断
                            keys[#keys + 1] = k
                        end
                    end
                end
            else
                keys[#keys + 1] = k
            end
        end
    end

    table.sort(keys, function(a, b)
        return a < b
    end)
    for index, key in pairs(keys) do
        local v = activities[key]
        local dojo = WelfareDojo.New()
        dojo:Fill(v)
        dojo.index = index
        table.insert(self._allWelfareDojo, dojo)
    end

    --- 判断是否有 需要打开指定id的位置（写作 parameters.selectedIndex 实际上是 welfareId ）
    local parameters = self.controller.Argument.parameters
    if (not isNull(parameters)) and (not isNull(parameters.selectedIndex)) then
        self._selectedIndex = self:GetIndexByWelfareId(parameters.selectedIndex)
        parameters.selectedIndex = nil
    end
end

function UIWelfareMainDialog:isOpenAdRewards()
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    local isChannel = SDKService:GetInstance():IsChannelSdk()
    if SDKService:GetInstance():IsForeignSDK() or isChannel then
        local isMobile = KTool.IsMobile()
        if isMobile then
            return true
        else
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
            local privilegeCardID = tonumber(vo.giftId)
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local isPrivilegeCard = false
            if playerComponent then
                local playerDojo = playerComponent.playerDojo
                local num = GameUtils.GetPrivilegeCardAddNumByName(tonumber(vo.giftId), "advertisement")
                if num == 1 then
                    isPrivilegeCard = playerDojo:IsHavePrivilegeCardById(privilegeCardID)
                end
            end
            return isPrivilegeCard
        end
    elseif KTool.UNITY_EDITOR() then
        return true
    end
    return false
end

---刷新自身
function UIWelfareMainDialog:RefreshSelf()
    self:InitWelfareDojo()
    self:InitToggleData()
    self:FillSelf()
end

