function UIWelfareMainDialog:OnFinalize()
    return CoWaitDo(function()
        local initParams = self.controller.Argument.parameters or {}
        initParams.prevSelectedIndex = self._selectedIndex

        self:UpdateActivityRedPoint()
        for _, node in pairs(self._activityNodes) do
            if not isNull(node.go) then
                KTool.SafeDelete(node.go.gameObject, true)
            end
        end
        self._activityNodes = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

return UIWelfareMainDialog
